Calls.Text:
JWT’s `exp` claim is a Unix timestamp in **seconds**, while `Date.now()` returns milliseconds. Comparing them directly uses different units.

Use either:

```js
const expired = Date.now() >= payload.exp * 1000;
```

or:

```js
const nowSeconds = Math.floor(Date.now() / 1000);
const expired = nowSeconds >= payload.exp;
```

A safe manual check:

```js
if (typeof payload.exp !== 'number' || Date.now() >= payload.exp * 1000) {
  return res.status(401).json({ error: 'Token expired or invalid' });
}

next();
```

However, it is better to let your JWT library verify expiration. With `jsonwebtoken`, `jwt.verify()` checks `exp` automatically:

```js
import jwt from 'jsonwebtoken';

function auth(req, res, next) {
  const token = req.headers.authorization?.replace(/^Bearer\s+/i, '');

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
      // audience: 'your-api',
      // issuer: 'your-issuer',
    });

    // jwt.verify rejects an expired exp, but require exp explicitly
    // if every token in your application must have one.
    if (typeof payload.exp !== 'number') {
      return res.status(401).json({ error: 'Token has no expiration' });
    }

    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({
      error: err.name === 'TokenExpiredError'
        ? 'Token expired'
        : 'Invalid token',
    });
  }
}
```

Also make sure you are not using `jwt.decode()` as authentication—it only parses the token and does not validate the signature or expiration. Avoid setting `ignoreExpiration: true`, and treat a token as expired when `now >= exp`, not only when `now > exp`.

