Calls.Text:
JWT’s `exp` claim is a **NumericDate in seconds since Unix epoch**, while `Date.now()` returns **milliseconds**.

So this comparison mixes units:

```js
Date.now() >= payload.exp // wrong
```

Use either:

```js
const nowSeconds = Math.floor(Date.now() / 1000);

if (typeof payload.exp !== 'number' || nowSeconds >= payload.exp) {
  return res.status(401).json({ error: 'Token expired' });
}
```

or convert `exp` to milliseconds:

```js
if (Date.now() >= payload.exp * 1000) {
  return res.status(401).json({ error: 'Token expired' });
}
```

Use `>=`, because the token is invalid at the instant specified by `exp`.

### Prefer letting the JWT library check it

With `jsonwebtoken`, `jwt.verify()` validates both the signature and expiration automatically:

```js
const jwt = require('jsonwebtoken');

function auth(req, res, next) {
  const header = req.get('authorization');
  const token = header?.startsWith('Bearer ')
    ? header.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
      // issuer: 'your-issuer',
      // audience: 'your-audience',
      // clockTolerance: 5, // optional, in seconds
    });

    req.user = payload;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }

    return res.status(401).json({ error: 'Invalid token' });
  }
}
```

Make sure you are not:

- Using `jwt.decode()` instead of `jwt.verify()`—`decode()` does not validate the signature or expiration.
- Passing `ignoreExpiration: true`.
- Calling `next()` after sending the 401 response.
- Creating `exp` in milliseconds. Generate it in seconds:

```js
const payload = {
  userId,
  exp: Math.floor(Date.now() / 1000) + 60 * 60, // one hour
};
```

Or let the library create it:

```js
jwt.sign({ userId }, process.env.JWT_SECRET, { expiresIn: '1h' });
```

