Calls.Text:
JWT’s standard `exp` claim is a Unix timestamp in **seconds**, while `Date.now()` returns milliseconds. Comparing them directly makes the units incompatible.

For example:

```js
// Wrong: milliseconds compared with seconds
if (Date.now() >= payload.exp) {
  // expired
}
```

Use seconds:

```js
const now = Math.floor(Date.now() / 1000);

if (typeof payload.exp !== 'number' || now >= payload.exp) {
  return res.status(401).json({ error: 'Token expired' });
}
```

However, don’t merely decode the token and manually check expiry. Verify its signature and claims with your JWT library. With `jsonwebtoken`, `jwt.verify()` checks `exp` automatically:

```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const header = req.get('authorization');

  if (!header?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const token = header.slice(7);

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'], // use the algorithm appropriate for your setup
    });

    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }

    return res.status(401).json({ error: 'Invalid token' });
  }
}
```

Also check that you are not passing `ignoreExpiration: true`. When creating tokens, use the library’s expiry option:

```js
const token = jwt.sign(payload, process.env.JWT_SECRET, {
  expiresIn: '1h',
});
```

If setting `exp` manually, it must also be in seconds:

```js
const exp = Math.floor(Date.now() / 1000) + 60 * 60;
```

