However, don’t merely decode the token and manually check expiry. Verify its signature and claims with your JWT library. With `jsonwebtoken`, `jwt.verify()` checks `exp` automatically:

```js
const jwt = require('jsonwebtoken');

function authenticate(req, res, next) {
  const header = req.get('authorization');

  if (!header?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }

  const token = header.slice(7);

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'], // use the algorithm appropriate for your setup
    });

    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
