Calls.Text:
Using the [`pg`](https://node-postgres.com/) package, create one long-lived `Pool` per Node.js process and reuse it for all requests.

```bash
npm install pg
```

### `db.js`

```js
import pg from 'pg';

const { Pool } = pg;

function requiredEnv(name) {
  const value = process.env[name];
  if (!value) throw new Error(`Missing required environment variable: ${name}`);
  return value;
}

export const pool = new Pool({
  connectionString: requiredEnv('DATABASE_URL'),

  // Maximum connections opened by this Node.js process.
  max: Number(process.env.DB_POOL_MAX ?? 10),

  // How long an unused connection remains in the pool.
  idleTimeoutMillis: Number(process.env.DB_IDLE_TIMEOUT_MS ?? 30_000),

  // Maximum time allowed to establish/acquire a connection.
  connectionTimeoutMillis: Number(
    process.env.DB_CONNECTION_TIMEOUT_MS ?? 5_000
  ),

  // Server-side PostgreSQL statement timeout.
  statement_timeout: Number(process.env.DB_STATEMENT_TIMEOUT_MS ?? 15_000),

  // Client-side query timeout. Set slightly above statement_timeout so the
  // server gets the first opportunity to cancel the statement cleanly.
  query_timeout: Number(process.env.DB_QUERY_TIMEOUT_MS ?? 16_000),

  keepAlive: true,
  application_name: process.env.APP_NAME ?? 'node-api',

  // Supported by current pg-pool versions; periodically replaces connections.
  maxLifetimeSeconds: Number(process.env.DB_MAX_LIFETIME_SECONDS ?? 300),

  // Configure this according to your provider's certificate requirements.
  ssl:
    process.env.NODE_ENV === 'production'
      ? {
          rejectUnauthorized: true,
          // For a private CA:
          // ca: process.env.DATABASE_CA_CERT,
        }
      : false,
});

// An error on an idle pooled client is emitted here.
// Without this listener, it can become an uncaught error.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
  });

  // Mark the app unhealthy or notify monitoring here.
  // Avoid immediately exiting unless your process manager will restart safely.
});

export async function verifyDatabaseConnection() {
  const client = await pool.connect();

  try {
    await client.query('SELECT 1');
  } finally {
    client.release();
  }
}

export async function closeDatabasePool() {
  await pool.end();
}
```

Do not set `rejectUnauthorized: false` merely to suppress TLS certificate errors. Use the CA certificate supplied by your database provider.

### Running ordinary queries

For one query, prefer `pool.query()`. It automatically checks out and releases a connection.

```js
import { pool } from './db.js';

export async function findUserById(id) {
  try {
    const result = await pool.query(
      `SELECT id, email, created_at
       FROM users
       WHERE id = $1`,
      [id]
    );

    return result.rows[0] ?? null;
  } catch (error) {
    console.error('Database query failed', {
      operation: 'findUserById',
      code: error.code,
      message: error.message,
    });

    // Let the HTTP/service layer decide how to present the error.
    throw error;
  }
}
```

Always use parameters such as `$1`; do not interpolate user input into SQL.

### Transactions

Transactions must use the same checked-out client for every statement. Always release the client in `finally`.

```js
import { pool } from './db.js';

export async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();
  let destroyClient = false;

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      // The connection may no longer be usable.
      destroyClient = true;
      console.error('Transaction rollback failed', {
        message: rollbackError.message,
        code: rollbackError.code,
      });
    }

    console.error('Transaction failed', {
      message: error.message,
      code: error.code,
    });

    throw error;
  } finally {
    // Passing true removes a broken client instead of returning it to the pool.
    client.release(destroyClient);
  }
}
```

### Startup and graceful shutdown

```js
import { verifyDatabaseConnection, closeDatabasePool } from './db.js';
import { app } from './app.js';

let server;

async function start() {
  try {
    await verifyDatabaseConnection();

    server = app.listen(process.env.PORT ?? 3000, () => {
      console.log('Server started');
    });
  } catch (error) {
    console.error('Database startup check failed', {
      message: error.message,
      code: error.code,
    });
    process.exit(1);
  }
}

async function shutdown(signal) {
  console.log(`Received ${signal}; shutting down`);

  // Stop accepting new HTTP requests first.
  if (server) {
    await new Promise((resolve) => server.close(resolve));
  }

  try {
    await closeDatabasePool();
    process.exit(0);
  } catch (error) {
    console.error('Failed to close PostgreSQL pool', error);
    process.exit(1);
  }
}

process.once('SIGTERM', () => void shutdown('SIGTERM'));
process.once('SIGINT', () => void shutdown('SIGINT'));

void start();
```

### Example environment

```env
DATABASE_URL=postgresql://app_user:secret@db.example.com:5432/app_db
DB_POOL_MAX=10
DB_CONNECTION_TIMEOUT_MS=5000
DB_IDLE_TIMEOUT_MS=30000
DB_STATEMENT_TIMEOUT_MS=15000
DB_QUERY_TIMEOUT_MS=16000
DB_MAX_LIFETIME_SECONDS=300
```

### Operational recommendations

- Create the pool once, not once per request.
- Size `max` across all application instances. For example, 10 instances with `max: 10` can consume 100 database connections.
- Reserve connections for migrations, administration, and background jobs.
- Use `pool.query()` for standalone queries and `pool.connect()` only when a transaction or session-specific state requires it.
- Always release manually acquired clients in `finally`.
- Set both connection and statement/query timeouts; they protect against different failures.
- Do not log connection strings, passwords, or complete query parameters.
- Retry only transient errors—such as connection resets, serialization failures (`40001`), or deadlocks (`40P01`)—and only when the operation is safe to retry. Use bounded exponential backoff rather than retrying every database error.

