## Pool configuration

```js
// db.js
import pg from 'pg';

const { Pool } = pg;

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,

  // Maximum clients opened by this application instance.
  max: Number(process.env.DB_POOL_MAX ?? 10),

  // Fail instead of waiting indefinitely for a connection.
  connectionTimeoutMillis: Number(
    process.env.DB_CONNECT_TIMEOUT_MS ?? 5_000
  ),

  // Close clients that have been idle in the pool.
  idleTimeoutMillis: Number(
    process.env.DB_IDLE_TIMEOUT_MS ?? 30_000
  ),

  // PostgreSQL server-side query timeout.
  statement_timeout: Number(
    process.env.DB_STATEMENT_TIMEOUT_MS ?? 10_000
  ),

  // Client-side timeout while awaiting a query result.
  query_timeout: Number(
    process.env.DB_QUERY_TIMEOUT_MS ?? 12_000
  ),

  // Protect against forgotten transactions.
  idle_in_transaction_session_timeout: Number(
    process.env.DB_IDLE_TX_TIMEOUT_MS ?? 15_000
  ),

  application_name: process.env.SERVICE_NAME ?? 'node-api',

  // Enable only if your provider requires TLS.
  ssl:
    process.env.DB_SSL === 'true'
      ? { rejectUnauthorized: true }
      : undefined,
});

// Required: idle clients can encounter network/server errors asynchronously.
pool.on('error', (error) => {
  console.error('Unexpected PostgreSQL pool error', {
    message: error.message,
    code: error.code,
    stack: error.stack,
  });

  // Report this to monitoring. Depending on your deployment strategy,
  // you may also mark the instance unhealthy and let it restart.
});
```

Example environment:

```env
DATABASE_URL=postgresql://app_user:secret@localhost:5432/app_db
DB_POOL_MAX=10
DB_CONNECT_TIMEOUT_MS=5000
DB_IDLE_TIMEOUT_MS=30000
DB_STATEMENT_TIMEOUT_MS=10000
DB_QUERY_TIMEOUT_MS=12000
DB_IDLE_TX_TIMEOUT_MS=15000
DB_SSL=false
```

Do not commit credentials to source control. In production, use a secret manager or injected environment variables.

## Running ordinary queries

Use `pool.query()` for single queries. It automatically checks out and releases a connection.

```js
// users.js
import { pool } from './db.js';

export async function findUserById(id) {
  try {
    const result = await pool.query(
      'SELECT id, email, created_at FROM users WHERE id = $1',
      [id]
    );

    return result.rows[0] ?? null;
  } catch (error) {
    console.error('Failed to query user', {
      code: error.code,
      message: error.message,
    });

    throw error;
  }
}
```

Always use parameterized queries (`$1`, `$2`, etc.) instead of string interpolation.

## Transactions

Transactions must use one checked-out client. Always release it in `finally`.

```js
import { pool } from './db.js';

export async function transferFunds(fromId, toId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch (rollbackError) {
      console.error('Transaction rollback failed', rollbackError);
    }

    throw error;
  } finally {
    client.release();
  }
}
```

Do not use separate `pool.query()` calls inside a transaction; each call could use a different connection.

## Startup check and graceful shutdown

```js
// server.js
import { pool } from './db.js';

async function start() {
  try {
    await pool.query('SELECT 1');
    console.log('PostgreSQL connection pool is ready');

    // Start HTTP server here.
  } catch (error) {
    console.error('Unable to connect to PostgreSQL', error);
    process.exit(1);
  }
}

let shuttingDown = false;

async function shutdown(signal) {
  if (shuttingDown) return;
  shuttingDown = true;

  console.log(`Received ${signal}; closing PostgreSQL pool`);

  try {
    // Stop accepting HTTP requests and wait for in-flight requests first.
    await pool.end();
    process.exit(0);
  } catch (error) {
    console.error('Failed to close PostgreSQL pool', error);
    process.exit(1);
  }
}

process.on('SIGTERM', () => void shutdown('SIGTERM'));
process.on('SIGINT', () => void shutdown('SIGINT'));

void start();
```

