    message: err.message,
    code: err.code,
  });

  // Usually log/alert and allow pg to remove the failed client.
  // Do not throw from this event handler.
});

async function query(text, params = []) {
  const startedAt = Date.now();

  try {
    return await pool.query(text, params);
  } catch (err) {
    console.error('PostgreSQL query failed', {
      message: err.message,
      code: err.code,
      durationMs: Date.now() - startedAt,
    });

