```tsx
import React, { ErrorInfo, ReactNode } from "react";

type ErrorBoundaryProps = {
  children: ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
};

type ErrorBoundaryState = {
  error: Error | null;
  retryCount: number;
};

export class ErrorBoundary extends React.Component<
  ErrorBoundaryProps,
  ErrorBoundaryState
> {
  state: ErrorBoundaryState = {
    error: null,
    retryCount: 0,
  };

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    // Replace or supplement this with your logging service.
    console.error("Unhandled render error:", {
      error,
      componentStack: info.componentStack,
    });

    this.props.onError?.(error, info);
  }

  private retry = () => {
    this.setState(({ retryCount }) => ({
      error: null,
      retryCount: retryCount + 1,
    }));
  };

  render() {
    const { error, retryCount } = this.state;

    if (error) {
      return (
        <div role="alert" style={{ padding: 16 }}>
          <h2>Something went wrong.</h2>
          <p>Please try again.</p>

          {process.env.NODE_ENV === "development" && (
            <pre style={{ whiteSpace: "pre-wrap", color: "crimson" }}>
              {error.message}
            </pre>
          )}

          <button type="button" onClick={this.retry}>
            Retry
          </button>
        </div>
      );
    }

    // The key ensures the child subtree is freshly mounted after a retry.
    return <React.Fragment key={retryCount}>{this.props.children}</React.Fragment>;
  }
}
```

Usage:

```tsx
function App() {
  return (
    <ErrorBoundary
      onError={(error, info) => {
        // Example: send to Sentry, Datadog, or your own API.
        logErrorToService({
          message: error.message,
          stack: error.stack,
          componentStack: info.componentStack,
        });
      }}
    >
      <MainApplication />
    </ErrorBoundary>
  );
}
```

Error boundaries catch errors during rendering, constructors, and lifecycle methods in descendant components. They do not catch errors from event handlers, asynchronous callbacks, server-side rendering, or errors thrown inside the boundary itself.

